var amount = Money.FromPiastres(request.AmountPiastres);
PurchasingRules.AssertPurchasePayment(amount, outstanding);
if (!amount.IsPositive) throw new DomainException("مبلغ السداد يجب أن يكون أكبر من صفر.");

