        Status = OrderStatus.Cancelled;
        IsPaid = false;
        ElectronicPayment = leg with { Status = ElectronicPaymentStatus.Cancelled };
        CancelledAtUtc = nowUtc;
        CancelReason = reason.Trim();
        CancelledBy = cancelledBy;
